const fs = require('fs');
const buf = fs.readFileSync(0);
let pos = 0;

function nextInt() {
    while (pos < buf.length && buf[pos] <= 32) pos++;
    let sign = 1;
    if (buf[pos] === 45) {
        sign = -1;
        pos++;
    }
    let num = 0;
    while (pos < buf.length && buf[pos] > 32) {
        num = num * 10 + (buf[pos] - 48);
        pos++;
    }
    return num * sign;
}

const L = nextInt();
const C = nextInt();

let prev = new Int32Array(C);
let curr = new Int32Array(C);

for (let j = 0; j < C; j++) {
    prev[j] = nextInt();
}

const n = C - 1;
const heights = new Int32Array(n);
const stackH = new Int32Array(n + 1);
const stackS = new Int32Array(n + 1);

let ans = Math.max(L, C);

for (let i = 0; i < L - 1; i++) {
    for (let j = 0; j < C; j++) {
        curr[j] = nextInt();
    }

    for (let j = 0; j < n; j++) {
        if (prev[j] + curr[j + 1] > prev[j + 1] + curr[j]) {
            heights[j] = 0;
        } else {
            heights[j]++;
        }
    }

    let top = 0;

    for (let j = 0; j <= n; j++) {
        const cur = j < n ? heights[j] : 0;
        let start = j;

        while (top > 0 && stackH[top - 1] > cur) {
            top--;
            const h = stackH[top];
            const st = stackS[top];
            const area = (h + 1) * (j - st + 1);
            if (area > ans) ans = area;
            start = st;
        }

        if (cur > 0 && (top === 0 || stackH[top - 1] < cur)) {
            stackH[top] = cur;
            stackS[top] = start;
            top++;
        }
    }

    const tmp = prev;
    prev = curr;
    curr = tmp;
}

process.stdout.write(String(ans));
